INSERT IGNORE INTO drug_clinical_info (drug_name, medicine_type, ingredients, indications, side_effects, allergic_reactions, contraindicated_groups, contraindications, interactions, dietary_taboos, dosing_interval_minutes, source) VALUES ('阿司匹林', 'western', '["乙酰水杨酸"]', '抗血小板聚集、解热镇痛、抗炎抗风湿', '["胃肠道不适", "胃溃疡", "出血倾向", "过敏反应"]', '["皮疹", "哮喘发作", "血管神经性水肿"]', '["孕妇晚期", "哺乳期", "儿童发热（Reye综合征风险）", "活动性溃疡", "严重肝肾功能不全", "血友病"]', '活动性消化性溃疡、血友病、严重肝肾功能不全、妊娠晚期禁用；对水杨酸过敏者禁用', '["抗凝药（华法林）", "其他NSAID", "甲氨蝶呤", "糖皮质激素"]', '["酒精（增加胃出血风险）"]', 30, 'NMPA+丁香园');
INSERT IGNORE INTO drug_clinical_info (drug_name, medicine_type, ingredients, indications, side_effects, allergic_reactions, contraindicated_groups, contraindications, interactions, dietary_taboos, dosing_interval_minutes, source) VALUES ('华法林', 'western', '["华法林钠"]', '抗凝治疗（心房颤动、心脏瓣膜置换、深静脉血栓、肺栓塞）', '["出血（牙龈、皮下、消化道、泌尿道）", "脱发", "皮疹", "肝功能异常"]', '["皮疹", "皮肤坏死（罕见）"]', '["孕妇", "严重高血压", "近期手术", "活动性出血", "严重肝肾功能不全"]', '妊娠期禁用、活动性出血、严重高血压未控制、近期手术或创伤、严重肝肾功能不全', '["阿司匹林", "广谱抗生素", "西咪替丁", "巴比妥类", "利福平", "维生素K", "丹参", "银杏叶", "当归"]', '["富含维生素K食物（菠菜、西兰花、甘蓝等绿叶菜）", "葡萄柚", "酒精"]', 30, 'NMPA+丁香园');
